const modal = document.querySelector('#modal');
const status = document.querySelector('#status');
const routes = [ ['inicio','⌂','Início'], ['agenda','◷','Agenda e rotina'], ['auria','✧','Assistente AURIA'], ['biblioteca','▤','Biblioteca'], ['saude','♡','Diário pessoal'], ['comunicacao','☷','Comunicação'], ['foco','◎','Trabalho e estudo'], ['apoio','♧','Rede de apoio'], ['acessibilidade','◉','Acessibilidade'], ['privacidade','◇','Privacidade'], ['ajuda','?','Ajuda e projeto'] ];
