let state, csrf, identityInfo={}, runtimeInfo={}, initialized = false, demo = false, route = 'inicio', search = '', timer = null, seconds = 25 * 60;
let conversation = [], reminderShown = new Set(), toastTimer, returnFocus, lastInteraction = Date.now();
let offlineSession=null,serverOffline=false;
let pendingSensitiveAction=null;
let installPrompt=null;
const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
const nowLocal = () => { const d = new Date(); return new Date(d.getTime() - d.getTimezoneOffset()*60000).toISOString().slice(0,16); };
const fmt = (date, options = {}) => new Intl.DateTimeFormat('pt-BR', { dateStyle:'short', timeStyle:'short', timeZone:state?.profile.timezone || 'America/Sao_Paulo', ...options }).format(new Date(date));
const dateLabel = () => new Intl.DateTimeFormat('pt-BR', { weekday:'long', day:'numeric', month:'long', timeZone:state.profile.timezone }).format(new Date());
function blank(name) { return { schema:2, revision:0, profile:{name,timezone:'America/Sao_Paulo'}, preferences:{theme:'dark',scale:100,reducedMotion:true,simple:false}, tasks:[], notes:[], memories:[], journal:[], contacts:[], consents:[], feedback:[], audit:[], prescriptions:[],medicationEvents:[],carePlans:[],nutritionPlans:[],activityPlans:[],grants:[],boards:[],documents:[] }; }
function toast(message) { status.textContent = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => status.textContent = '', 6500); }
async function api(path, method='GET', body, mutationId) {
  if(globalThis.AURA_BROWSER_MODE){try{return await globalThis.AuraBrowserAPI(path,method,body,mutationId);}catch(error){if(error.status===401&&state&&path!=='reauth'){state=null;csrf=null;welcome();}throw error;}}
  const response = await fetch('/api/' + path, { method, headers:{...(body ? {'Content-Type':'application/json'} : {}), ...(csrf ? {'X-Aura-CSRF':csrf} : {}),...(mutationId?{'X-Aura-Mutation':mutationId}:{})}, ...(body ? {body:JSON.stringify(body)} : {}) });
  const result = await response.json();
  if (!response.ok) { if (response.status === 401 && state && !demo&&path!=='reauth') { state = null; csrf = null; welcome(); } const error=new Error(result.error || 'Não foi possível concluir.');error.details=result.details;error.status=response.status;throw error; }
  return result;
}
function prefs() {
  const p = state?.preferences || {theme:'dark',scale:100};
  document.documentElement.dataset.theme = p.theme;
  document.documentElement.classList.remove('scale-100','scale-125','scale-150','scale-200');
  document.documentElement.classList.add('scale-' + p.scale);
  document.body.classList.toggle('no-motion', !!p.reducedMotion);
  document.body.classList.toggle('simple', !!p.simple);
}
async function change(kind, method, data, id) {
  if(!demo&&(serverOffline||offlineSession?.operations.length)){await queueOffline(kind,method,data,id);return;}
  if (demo) {
    const scope = kind === 'journal' ? 'health' : kind === 'memories' ? 'memory' : null;
    if (method !== 'DELETE' && scope && !hasConsent(scope)) throw new Error('Ative o consentimento específico em Privacidade.');
    if (kind === 'preferences') { Object.assign(state.preferences,data); }
    else if (method === 'POST') {
      if (kind === 'consents') state.consents = state.consents.filter(c => c.scope !== data.scope);
      state[kind].push({...data,id:crypto.randomUUID(),createdAt:new Date().toISOString(),...(kind==='memories' ? {source:'declarada pelo usuário'} : {})});
    } else if (method === 'DELETE') state[kind] = state[kind].filter(item => item.id !== id);
    else {
      const old=state[kind].find(item => item.id === id);
      if(kind==='tasks'&&data.done===true&&!old.done&&!old.nextOccurrenceId&&['daily','weekly'].includes(old.recurrence)){const nextId=crypto.randomUUID();state.tasks.push({...old,id:nextId,startsAt:new Date(Date.parse(old.startsAt)+(old.recurrence==='daily'?86400000:604800000)).toISOString(),done:false});old.nextOccurrenceId=nextId;}
      Object.assign(old,data);
    }
    state.audit.push({id:crypto.randomUUID(),at:new Date().toISOString(),action:method.toLowerCase(),object:kind});
  } else {const mutationId=crypto.randomUUID();try{state = await api(kind + (id ? '/' + id : ''), method, data,mutationId);}catch(error){if(error instanceof TypeError&&offlineSession){serverOffline=true;await queueOffline(kind,method,data,id,mutationId);return;}throw error;}}
  if(offlineSession&&!demo){offlineSession.baseRevision=state.revision;await globalThis.AuraOffline.save(offlineSession,state);}
  prefs(); render();
}
async function queueOffline(kind,method,data,id,mutationId=crypto.randomUUID()){
  if(!offlineSession||!['tasks','notes','preferences'].includes(kind))throw new Error('No modo offline, edite apenas agenda, notas e preferências. Outros recursos exigem o serviço online.');
  if(offlineSession.operations.length>197)throw new Error('Sincronize antes de adicionar mais alterações offline.');
  if(method==='POST')id=crypto.randomUUID();
  if(kind==='preferences')Object.assign(state.preferences,data);
  else{
    const index=state[kind].findIndex(r=>r.id===id),old=index>=0?state[kind][index]:{};
    if(method==='DELETE'){if(index>=0)state[kind].splice(index,1);}
    else{
      const record={...old,...data,id,createdAt:old.createdAt||new Date().toISOString()};
      if(kind==='tasks'&&data.done===true&&!old.done&&!old.nextOccurrenceId&&['daily','weekly'].includes(old.recurrence)){
        const next={...record,id:crypto.randomUUID(),done:false,startsAt:new Date(Date.parse(record.startsAt)+(record.recurrence==='daily'?86400000:604800000)).toISOString()};
        state.tasks.push(next);offlineSession.operations.push({kind:'tasks',method:'POST',id:next.id,data:next,mutationId:crypto.randomUUID()});record.nextOccurrenceId=next.id;
      }
      if(index>=0)state[kind][index]=record;else state[kind].push(record);data=record;
    }
  }
  offlineSession.operations.push({kind,method,id,data,mutationId});
  await globalThis.AuraOffline.save(offlineSession,state);prefs();render();toast('Alteração guardada na cópia offline criptografada.');
}
function offlineWelcome(){app.innerHTML='<main id="main" class="content"><p class="eyebrow">CÓPIA ESSENCIAL OFFLINE</p><h1>Seu espaço continua aqui.</h1><p>Abra a cópia criptografada deste navegador para consultar agenda e notas. Dados de saúde e delegações não são guardados nesta cópia.</p><form id="offline-unlock-form"><label>Senha usada ao ativar a cópia offline<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Abrir cópia offline</button></form><p class="subtle section-gap">A exclusão de dados do navegador remove esta cópia e as alterações ainda não sincronizadas.</p><button data-action="reload">Tentar o serviço online</button></main>';}
function hasConsent(scope) { return state.consents.some(c => c.scope === scope && c.granted); }
function header(title, subtitle, action='') { return `<div class="page-header"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${action}</div>`; }
function empty(message) { return `<div class="empty">${message}</div>`; }
function welcome() {
  if(identityInfo.enabled&&!identityInfo.signedIn){
    app.innerHTML=`<main id="main" class="welcome"><section class="welcome-story"><a class="brand" href="/"><img src="./icon.svg" alt="">AURA OS</a><h1>Seu espaço.<br>Sua identidade.</h1><p>O AURA ID separa as contas e protege o acesso ao seu espaço. Seu cofre continua protegido por uma senha própria.</p></section><section class="welcome-form"><div><p class="eyebrow">AURA ID</p><h2>Entre ou crie sua conta</h2><p class="muted">Você será direcionado ao serviço de identidade local. Gerencie senha e fatores de autenticação nas configurações da conta.</p><a class="button primary" href="/auth/login">Continuar com AURA ID →</a><p class="subtle section-gap">A conta não exige um diagnóstico. O cofre pode ser criado depois da autenticação.</p><button data-action="demo">Explorar demonstração</button><div class="welcome-access"><button data-action="welcome-contrast">Alternar contraste</button><button data-action="welcome-scale">Ampliar texto</button></div></div></section></main>`;return;
  }
  app.innerHTML = `<main id="main" class="welcome"><section class="welcome-story"><a class="brand" href="/"><img src="./icon.svg" alt="">AURA OS</a><p class="eyebrow">SEU ESPAÇO DE AUTONOMIA</p><h1>Seu dia.<br>Do seu jeito.</h1><p>Menos barreiras, mais possibilidades. Um espaço acessível para organizar sua rotina, se comunicar e cuidar do que importa.</p><div class="decorative"><p>◷ &nbsp; Rotinas que respeitam seu ritmo</p><p>◉ &nbsp; Acessibilidade sob seu controle</p><p>◇ &nbsp; Seus dados permanecem neste aparelho</p></div><small>Primeira versão local · AURA Prism · Português brasileiro</small></section><section class="welcome-form"><div><p class="eyebrow">BEM-VINDO AO AURA</p><h2>${initialized ? 'Abra seu espaço' : 'Vamos começar?'}</h2><p class="muted">${initialized ? 'Use a senha do seu cofre local para continuar.' : 'Crie um cofre pessoal protegido. Nenhum diagnóstico é necessário.'}</p><form id="auth-form">${!initialized ? '<label>Como prefere ser chamado?<input name="name" autocomplete="given-name" maxlength="100" required></label>' : ''}<label>Senha do cofre<input name="password" type="password" autocomplete="${initialized?'current-password':'new-password'}" minlength="12" maxlength="200" required aria-describedby="password-help"></label><small id="password-help">${initialized ? 'Não há recuperação por e-mail. A senha protege a chave dos dados locais.' : 'Use pelo menos 12 caracteres. Guarde a senha: não há recuperação nesta versão.'}</small>${!initialized?'<label>Repita a senha<input name="confirm" type="password" autocomplete="new-password" minlength="12" required></label>':''}<div id="auth-error" role="alert" class="error"></div><button class="primary" type="submit">${initialized?'Desbloquear meu cofre':'Criar meu espaço'} →</button></form><p class="subtle section-gap">Quer conhecer primeiro? A demonstração usa somente dados fictícios e não os salva.</p><button data-action="demo" class="ghost">Explorar demonstração</button><div class="welcome-access"><button data-action="welcome-contrast">Alternar contraste</button><button data-action="welcome-scale">Ampliar texto</button></div><p class="subtle section-gap">Uso local experimental. Validação de acessibilidade e revisão independente ainda pendentes. Os recursos de registro não substituem atendimento profissional.</p></div></section></main>`;
  if(initialized)document.querySelector('#auth-form').insertAdjacentHTML('afterend','<button class="ghost section-gap" data-action="recover">Usar meu código de recuperação do cofre</button>');
  document.querySelector('#password-help').textContent=initialized?'A recuperação exige um código criado anteriormente em Privacidade. Não há recuperação do cofre por e-mail.':'Use pelo menos 12 caracteres. Depois, você poderá criar um código de recuperação em Privacidade.';
  if(globalThis.AURA_BROWSER_MODE)document.querySelector('.welcome-form>div').insertAdjacentHTML('afterbegin','<p class="notice">Cofre deste navegador · Os registros ficam criptografados neste aparelho, sem conta na nuvem. Limpar os dados do site ou usar navegação privada pode apagá-los. Faça backups em Privacidade. Use dados fictícios nesta versão experimental.</p>');
  if(globalThis.AURA_BROWSER_MODE){document.querySelector('.welcome-form>div').insertAdjacentHTML('beforeend',`${!initialized?'<button class="ghost section-gap" data-action="import-vault">Importar meu cofre do desktop</button>':''}<button class="ghost section-gap" data-action="install-web">Instalar AURA Web neste aparelho</button>`);}
}
