  if(route==='auria')document.querySelector('#main').insertAdjacentHTML('beforeend','<section class="card section-gap"><h2>Ações com revisão</h2><p>Prepare uma atividade pessoal, confira todos os campos e confirme antes de salvar. O assistente não executa esta ação por conta própria.</p><button data-action="action-preview-new">Preparar atividade para revisão</button></section>');
