function taskList(tasks) {
  if (!tasks.length) return empty('Nenhuma atividade por aqui. Crie uma rotina no seu ritmo.');
  return `<ul class="list">${tasks.map(t=>`<li class="list-item ${t.done?'task-done':''}"><div class="row"><div class="task-main"><button class="task-check" data-action="task-toggle" data-id="${t.id}" aria-label="${t.done?'Reabrir':'Concluir'}: ${e(t.title)}" aria-pressed="${!!t.done}">${t.done?'✓':'○'}</button><div><div class="task-title">${e(t.title)}</div><small>${e(fmt(t.startsAt))} · ${e(t.category)}${t.recurrence && t.recurrence!=='none'?' · '+(t.recurrence==='daily'?'Diária':'Semanal'):''}</small></div></div><div class="actions"><button class="icon-button ghost" data-action="task-snooze" data-id="${t.id}" aria-label="Adiar ${e(t.title)} por 10 minutos">+10 min</button><button class="icon-button ghost" data-action="task-edit" data-id="${t.id}" aria-label="Editar ${e(t.title)}">Editar</button><button class="icon-button ghost danger" data-action="delete" data-kind="tasks" data-id="${t.id}" aria-label="Excluir ${e(t.title)}">×</button></div></div></li>`).join('')}</ul>`;
}
const pages = {
  catalogo(){return `${header('Condições, deficiências e apoios','Fontes públicas para aprender e preparar perguntas para uma equipe de saúde.')}<div id="health-catalog"></div>`;},
  cuidados(){return `${header('Seus planos, como foram orientados.','Registre planos e prescrições existentes para consultar e preparar conversas com profissionais.')}<div class="notice">Os registros são transcritos pelo usuário e não são verificados pelo AURA. Nenhum cadastro equivale a aprovação profissional. Não alteramos doses, dietas, tratamentos ou progressões de exercício. Lembretes são criados separadamente na agenda.</div><div class="settings-grid">${['prescriptions','carePlans','nutritionPlans','activityPlans'].map(resourceCard).join('')}</div>`;},
  documentos(){return `${header('Documentos sob seu controle.','Leia, extraia e revise o texto antes de guardá-lo.')}<div class="notice">Processamento neste dispositivo: TXT, Markdown e PDF que já contém texto. Limite de 10 MB por arquivo e 50.000 caracteres extraídos. Reconhecimento pode conter erros; confira o original. Imagens e PDFs digitalizados sem camada de texto não são reconhecidos nesta edição, que não usa OCR treinado.</div><section class="card"><form id="document-import-form"><label>Arquivo para leitura<input name="file" type="file" accept=".txt,.md,.pdf" required></label><button>Extrair e revisar texto</button><p id="import-progress" role="status"></p></form></section>${resourceCard('documents')}`;},
  delegacao(){return `${header('Apoio com limites claros.','Acesso identificado, com finalidade, escopo, prazo e revogação.')}<div class="notice">Esta delegação funciona entre contas AURA ID no serviço local. O titular precisa manter o cofre desbloqueado. Não há envio de convites, acesso pela internet ou disponibilidade quando o titular fecha a sessão.</div><section class="card"><h2>Sua identificação AURA ID</h2><p class="prose">${e(identityInfo.user?.subject||'Disponível no modo Plataforma com AURA ID.')}</p><button data-action="grant-new">Autorizar uma pessoa</button><ul class="list">${(state.grants||[]).map(g=>`<li class="list-item"><h3>${e(g.recipient)}</h3><p>${e(g.purpose)}</p><p class="subtle">${e(g.scopes.join(', '))} · até ${e(fmt(g.expiresAt))} · ${g.revoked?'Revogado':Date.parse(g.expiresAt)>Date.now()?'Vigente':'Expirado'}</p><button data-action="grant-revoke" data-id="${g.id}" ${g.revoked?'disabled':''}>Revogar acesso</button></li>`).join('')}</ul></section><section class="card section-gap"><h2>Consultar dados autorizados</h2><form id="delegated-form"><label>Identificação AURA ID do titular<input name="owner" required maxlength="200"></label><label>Informação autorizada<select name="scope">${[['tasks','Agenda'],['notes','Notas'],['journal','Diário'],['prescriptions','Prescrições'],['carePlans','Cuidados'],['nutritionPlans','Alimentação'],['activityPlans','Atividade']].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><button>Consultar autorização e registros</button></form><div id="delegated-result" class="section-gap" role="status"></div></section>`;},
  inicio() {
    const pending = state.tasks.filter(t=>!t.done).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt));
    const done = state.tasks.filter(t=>t.done).length;
    return `${header(`Olá, ${e(state.profile.name)}.`, 'Um passo de cada vez. Este espaço acompanha o seu ritmo.')}<div class="grid"><div><section class="card hero"><img class="hero-mark decorative" src="./icon.svg" alt=""><p class="eyebrow">${e(dateLabel())}</p><h2>Hoje, o importante<br>é o que importa para você.</h2><p class="muted">Organize seus compromissos, faça uma pausa e encontre as ferramentas que tornam seu dia mais leve.</p><button class="primary" data-action="task-new">+ Adicionar atividade</button></section><div class="cards"><div class="card"><small>Para fazer</small><div class="stat">${pending.length}</div><small>No seu ritmo</small></div><div class="card"><small>Concluídas</small><div class="stat">${done}</div><small>Cada passo conta</small></div><div class="card"><small>Suas notas</small><div class="stat">${state.notes.length}</div><small>Ideias guardadas</small></div></div><section class="card"><div class="card-header"><h2>Próximas atividades</h2><a href="#agenda">Ver agenda →</a></div>${taskList(pending.slice(0,3))}</section></div><div class="stack"><section class="card"><div class="auria-orb decorative" aria-hidden="true">✧</div><div class="card-header"><h2>Conte com a AURIA</h2><span class="pill">Local</span></div><p class="muted">Uma ajuda para encontrar seu próximo passo. Seus dados ficam aqui.</p><a href="#auria" class="button">Conversar com a AURIA →</a><p class="subtle section-gap">Motor próprio de comandos, busca e resumo. Sem modelos de terceiros.</p></section><section class="card"><h2>O que você precisa agora?</h2><div class="quick-grid"><a href="#comunicacao" class="quick-link">☷ Comunicar<small>Frases e leitura em voz alta</small></a><a href="#acessibilidade" class="quick-link">◉ Adaptar<small>Seu jeito de interagir</small></a><a href="#foco" class="quick-link">◎ Concentrar<small>Um tempo para cada coisa</small></a><a href="#biblioteca" class="quick-link">▤ Anotar<small>Libere espaço na mente</small></a></div></section><p class="subtle">◇ Sem anúncios, rastreadores ou envio para nuvem nesta versão.</p></div></div>`;
  },
  agenda() {
    return `${header('Seu tempo, seu ritmo.','Atividades com horário, fuso e confirmação.', '<button class="primary" data-action="task-new">+ Nova atividade</button>')}<div class="notice">Lembretes são verificados enquanto esta janela está aberta e o computador está ativo. Ao reabrir, atividades atrasadas serão mostradas. A repetição cria o próximo item após concluir o atual, mantendo o intervalo em horas; revise o horário em mudanças de horário de verão.</div><div class="row"><p class="subtle">Fuso de exibição: ${e(state.profile.timezone)}</p><button data-action="notifications">Ativar notificações</button></div><section class="card">${taskList([...state.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||Date.parse(a.startsAt)-Date.parse(b.startsAt)))}</section>`;
  },
  auria() { return `${header('Vamos por partes.','Uma ajuda transparente para organizar seu dia.')}<section class="card"><div class="notice">AURIA · Motor próprio de comandos, busca e resumo extrativo. Não é um modelo de conversa geral. Registros só são consultados nos escopos que você escolher; não executa ações externas nem fornece diagnóstico ou prescrição.</div><div class="conversation" role="log" aria-label="Conversa com AURIA">${conversation.length?conversation.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><small>${m.role==='user'?'Você':'✧ AURIA'}</small><p class="prose">${e(m.text)}</p>${m.source?`<small>Origem: ${e(m.source)}</small>`:''}${m.suggestions?.length?`<div class="actions section-gap">${m.suggestions.filter(s=>routes.some(r=>r[0]===s.route)||s.action==='prepare-task').map(s=>`<button data-action="${s.action==='prepare-task'?'action-preview-new':'assistant-navigate'}" data-route="${e(s.route||'')}">${e(s.label)}</button>`).join('')}</div>`:''}</div>`).join(''):'<div class="bubble"><p>Olá! Posso ajudar a consultar suas atividades. Experimente: “Como está minha agenda?”</p><small>Resposta por regras locais. Nenhum dado enviado a terceiros.</small></div>'}</div><form id="chat-form"><label for="chat">Como posso ajudar?</label><div class="form-row"><input id="chat" name="message" maxlength="2000" placeholder="Como está minha agenda?" required><button class="primary">Enviar pergunta →</button></div></form><button class="ghost section-gap" data-action="clear-chat">Limpar conversa</button></section>`; },
  biblioteca() {
    const visible = item => (item.title+' '+item.content).toLowerCase().includes(search.toLowerCase());
    const memories = state.memories.filter(m=>!m.expiresAt || Date.parse(m.expiresAt)>Date.now());
    const items = (kind,list) => list.filter(visible).length ? `<ul class="list">${list.filter(visible).map(n=>`<li class="list-item"><h3>${e(n.title)}</h3><p class="prose">${e(n.content)}</p><small>${e(n.source||'Registrada por você')} · ${e(fmt(n.createdAt))}${n.expiresAt?' · expira '+e(fmt(n.expiresAt)):''}</small><div class="actions section-gap"><button data-action="entry-edit" data-kind="${kind}" data-id="${n.id}">Editar</button><button class="danger" data-action="delete" data-kind="${kind}" data-id="${n.id}">Excluir</button></div></li>`).join('')}</ul>` : empty('Nada registrado aqui ainda.');
    return `${header('Ideias, lembranças e possibilidades.','Guarde só o que você escolher. Edite ou apague quando quiser.')}<form id="search-form" class="search"><label>Buscar na biblioteca<input name="search" value="${e(search)}" placeholder="Título ou conteúdo"></label><button>Buscar</button></form><div class="grid"><section class="card"><div class="card-header"><h2>Minhas notas</h2><button data-action="entry-new" data-kind="notes">+ Nova nota</button></div>${items('notes',state.notes)}</section><section class="card"><div class="card-header"><h2>Memórias explícitas</h2><button data-action="entry-new" data-kind="memories">+ Memória</button></div><p class="subtle">Somente informações que você registrar. Não inferimos dados sensíveis. Memórias expiradas deixam de aparecer, mas permanecem no cofre até você excluí-las pelo painel de dados.</p>${!hasConsent('memory')?'<p class="notice">Ative a memória local em <a href="#privacidade">Privacidade</a> antes de registrar.</p>':''}${items('memories',memories)}</section></div>`;
  },
  saude() { return `${header('Um registro para você.','Anotações pessoais para preparar suas conversas com profissionais.', '<button class="primary" data-action="entry-new" data-kind="journal">+ Novo registro</button>')}<div class="notice">Estes são relatos pessoais, sem validação clínica. O AURA não interpreta sintomas nem recomenda tratamentos. Use apenas dados de teste nesta fase experimental.</div>${!hasConsent('health')?'<p class="notice">Autorize o diário pessoal em <a href="#privacidade">Privacidade</a> para registrar.</p>':''}<section class="card">${state.journal.length?`<ul class="list">${[...state.journal].reverse().map(n=>`<li class="list-item"><small>${e(fmt(n.createdAt))} · Relato do usuário</small><h2>${e(n.title)}</h2><p class="prose">${e(n.content)}</p><div class="actions"><button data-action="entry-edit" data-kind="journal" data-id="${n.id}">Editar</button><button class="danger" data-action="delete" data-kind="journal" data-id="${n.id}">Excluir</button></div></li>`).join('')}</ul>`:empty('Seu diário está vazio. Não é necessário registrar informações de saúde para usar o AURA.')}</section>`; },
  comunicacao() { return `${header('Sua voz tem muitas formas.','Escolha uma frase ou escreva o que deseja comunicar.')}<div class="notice">A leitura usa as vozes disponíveis no navegador e no sistema. Não ativamos microfone. A disponibilidade e o processamento da voz dependem do dispositivo.</div><section class="card"><div class="caa">${[['☀','Olá, bom dia!'],['♡','Preciso de ajuda.'],['◷','Preciso de uma pausa.'],['♧','Quero falar com alguém.'],['✓','Sim.'],['×','Não.']].map(([icon,phrase])=>`<button data-action="speak" data-text="${e(phrase)}"><span class="caa-symbol" aria-hidden="true">${icon}</span>${phrase}</button>`).join('')}</div><form id="speak-form" class="section-gap"><label>Escreva sua mensagem<textarea name="text" maxlength="2000" required placeholder="O que você gostaria de dizer?"></textarea></label><div class="actions"><button class="primary">Ler em voz alta</button><button type="button" data-action="stop-speech">Parar leitura</button></div></form><p id="speech-text" class="prose section-gap" role="status"></p></section>`; },
  foco() { return `${header('Uma coisa de cada vez.','Um espaço simples para trabalho e estudo, com pausas no seu ritmo.')}<div class="grid"><section class="card"><h2>Seu tempo de foco</h2><p class="muted">25 minutos é apenas um ponto de partida. Você escolhe quando começar e parar.</p><div class="focus-timer" id="timer" role="timer" aria-label="Tempo restante">${timerLabel()}</div><div class="actions"><button class="primary" data-action="timer-toggle">${timer?'Pausar':'Começar'}</button><button data-action="timer-reset">Reiniciar</button><button data-action="timer-short">Usar 5 minutos</button></div><p class="subtle section-gap">Contagem apenas com esta sessão aberta; não substitui alarmes do sistema.</p></section><section class="card"><h2>Divida em pequenos passos</h2><p class="muted">Transforme um objetivo em atividades menores. Registre uma de cada vez e ajuste quando precisar.</p><button data-action="task-new">+ Criar um passo</button><a class="button ghost section-gap" href="#biblioteca">Abrir minhas notas</a></section></div>`; },
  apoio() { return `${header('Pessoas que fazem parte do caminho.','Contatos de confiança, sempre sob seu controle.', '<button class="primary" data-action="contact-new">+ Adicionar contato</button>')}<div class="notice">Esta versão mantém uma agenda de contatos local. Convites, contas de cuidadores e compartilhamento remoto ainda não estão implementados. Salvar um contato não concede acesso a dados.</div><section class="card">${contactList()}</section>`; },
  acessibilidade() { return `${header('Seu jeito de interagir.','Configure suas preferências sem precisar informar um diagnóstico.')}<div class="settings-grid"><section class="card"><h2>Leitura e aparência</h2><form id="preferences-form"><label>Tema<select name="theme">${[['dark','AURA escuro'],['light','Claro'],['contrast','Alto contraste']].map(([v,t])=>`<option value="${v}" ${state.preferences.theme===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Tamanho do texto<select name="scale">${[100,125,150,200].map(v=>`<option value="${v}" ${state.preferences.scale===v?'selected':''}>${v}%</option>`).join('')}</select></label><label class="check"><input name="reducedMotion" type="checkbox" ${state.preferences.reducedMotion?'checked':''}>Reduzir movimento</label><label class="check"><input name="simple" type="checkbox" ${state.preferences.simple?'checked':''}>Reduzir elementos decorativos</label><button class="primary">Salvar minhas preferências</button></form></section><section class="card"><h2>Navegação no seu ritmo</h2><p>Use Tab e Shift + Tab para navegar. Pressione Enter para ativar links e botões. Esc fecha as janelas de edição.</p><p>A interface inclui rótulos, foco visível, regiões semânticas e mensagens de status.</p><p class="subtle">Leitores de tela e dispositivos alternativos dependem dos recursos do sistema. Testes com NVDA, VoiceOver, TalkBack e usuários reais ainda pendentes.</p><button data-action="speak" data-text="Bem-vindo ao AURA. Você escolhe o seu ritmo.">Testar leitura em voz alta</button><h2 class="section-gap">Perfil</h2><form id="profile-form"><label>Seu nome<input name="name" value="${e(state.profile.name)}" maxlength="100" required></label><label>Fuso horário IANA<input name="timezone" value="${e(state.profile.timezone)}" required></label><button>Salvar perfil</button></form></section></div>`; },
  privacidade() {
    return `${header('Seus dados. Suas escolhas.','Saiba o que está guardado, revise permissões e leve seus registros com você.')}<div class="settings-grid"><section class="card"><h2>Consentimentos locais</h2><p class="muted">Tudo desativado por padrão. Revogar impede novos registros; você pode apagar registros já existentes.</p>${[['memory','Memória explícita','Lembranças que você escolhe registrar, com finalidade e validade opcional.'],['health','Diário pessoal','Relatos pessoais opcionais, guardados no cofre local.']].map(([scope,title,desc])=>`<div class="list-item"><h3>${title}</h3><p class="subtle">${desc}</p><button data-action="consent" data-scope="${scope}" aria-pressed="${hasConsent(scope)}">${hasConsent(scope)?'Revogar autorização':'Autorizar armazenamento local'}</button></div>`).join('')}<p class="subtle">Áudio capturado, câmera, localização, treinamento e parceiros: não integrados, sem coleta.</p></section><section class="card"><h2>Portabilidade e exclusão</h2><p class="muted">O cofre é criptografado no disco. A exportação JSON contém seus dados em texto legível: escolha onde guardá-la.</p><div class="stack"><button data-action="export">Exportar meus dados</button><button data-action="backup">Baixar cópia criptografada</button><button class="danger" data-action="erase">Apagar meu cofre</button></div><p class="subtle section-gap">A recuperação exige um código criado previamente. Cópias exportadas e backups são responsabilidade de quem os mantém. Exclusão do arquivo não garante apagamento físico em SSDs ou backups externos.</p></section><section class="card"><h2>Registros armazenados</h2><div class="status-list">${['tasks','notes','memories','journal','contacts','feedback','prescriptions','medicationEvents','carePlans','nutritionPlans','activityPlans','grants','boards','documents'].map(k=>`<div><span>${({tasks:'Atividades',notes:'Notas',memories:'Memórias (inclui expiradas)',journal:'Diário',contacts:'Contatos',feedback:'Relatos de suporte',prescriptions:'Prescrições informadas',medicationEvents:'Eventos declarados',carePlans:'Planos de cuidado',nutritionPlans:'Planos alimentares',activityPlans:'Planos de atividade',grants:'Autorizações de apoio',boards:'Frases de comunicação',documents:'Documentos em texto'})[k]}</span><span>${state[k].length}</span></div>`).join('')}</div>${state.memories.some(m=>m.expiresAt&&Date.parse(m.expiresAt)<=Date.now())?'<button class="section-gap" data-action="expired-delete">Excluir memórias expiradas</button>':''}<p class="subtle section-gap">A consulta normal oculta memórias expiradas; a exportação ainda as inclui até a exclusão.</p></section><section class="card"><h2>Histórico de alterações</h2><p class="subtle">Até 1.000 eventos locais. Registra tipos de operação, sem o conteúdo dos relatos. Não é uma auditoria imutável independente.</p><ul class="list audit">${state.audit.slice(-12).reverse().map(a=>`<li class="list-item">${e(fmt(a.at))} · ${e(a.action)} · ${e(a.object)}</li>`).join('')||'<li>Nenhuma alteração registrada.</li>'}</ul></section></div>`;
  },
  ajuda() { return `${header('Um projeto construído com evidências.','Versão experimental 0.6.0 baseada no plano diretor AURA OS V16.')}<div class="settings-grid"><section class="card"><h2>Disponível nesta versão</h2><ul><li>Cofre local com senha e criptografia</li><li>Agenda, repetição por intervalo e lembretes com janela aberta</li><li>Notas, memórias explícitas e diário opcional</li><li>Preferências de acessibilidade e comunicação por frases</li><li>Contatos locais, exportação e exclusão</li><li>AURIA por comandos locais</li></ul><h2>Como abrir novamente</h2><p>Execute <strong>Iniciar AURA OS.cmd</strong> na pasta do projeto e abra <strong>http://127.0.0.1:4310</strong>.</p></section><section class="card"><h2>Próximas entregas</h2><div class="status-list">${[['AURA ID / passkeys / MFA','Modo Plataforma'],['PostgreSQL / sincronização','Implementação local'],['Windows portátil','Experimental'],['Android/iOS nativos','Pendente'],['IA local','Opcional, com consentimento'],['Integrações clínicas / SUS','Dependem de acordos'],['Validação WCAG com usuários','Pendente'],['Operação 24 horas','Não implantada']].map(([a,b])=>`<div><span>${a}</span><small class="badge-pending">${b}</small></div>`).join('')}</div><p class="subtle section-gap">Esta versão é um incremento local, não a execução completa das 150 seções. Consulte os documentos do projeto para a matriz de requisitos e limitações.</p></section><section class="card"><h2>Feedback e suporte</h2><p>Registre um problema ou sugestão. O relato fica apenas neste cofre, sem envio a uma equipe. Você pode exportá-lo em Privacidade.</p><button data-action="entry-new" data-kind="feedback">Registrar relato local</button>${state.feedback.map(f=>`<div class="list-item"><h3>${e(f.title)}</h3><p class="prose">${e(f.content)}</p><button class="danger" data-action="delete" data-kind="feedback" data-id="${f.id}">Excluir relato</button></div>`).join('')}</section><section class="card"><h2>Privacidade no primeiro uso</h2><p>Não há envio automático de dados, métricas, mensagens ou arquivos. A aplicação escuta somente no endereço local deste computador.</p><p>Sem acesso ao microfone, à câmera ou à localização. A voz depende do mecanismo de síntese do navegador.</p><p class="subtle">Revisões independentes de segurança, acessibilidade e riscos clínicos são etapas futuras antes de uso público.</p></section></div>`; }
};
function contactList() { return state.contacts.length?`<ul class="list">${state.contacts.map(c=>`<li class="list-item"><div class="row"><div><h3>${e(c.name)}</h3><a class="button" href="tel:${e(c.phone.replace(/[^+\d]/g,''))}">${e(c.phone)}</a></div><button class="danger" data-action="delete" data-kind="contacts" data-id="${c.id}">Excluir contato</button></div></li>`).join('')}</ul>`:empty('Adicione pessoas de confiança para encontrá-las rapidamente.'); }
function resourceCard(kind){const config=globalThis.AuraResources?.[kind];if(!config)return '';return `<section class="card section-gap"><div class="card-header"><h2>${config.title}</h2><button data-action="resource-new" data-kind="${kind}">+ Adicionar</button></div>${(state[kind]||[]).length?`<ul class="list">${state[kind].map(r=>`<li class="list-item"><h3>${e(r.title)}</h3><p class="prose">${e(r.content||r.instructions||r.phrase)}</p>${r.source?`<small>Origem: ${e(r.source)}</small>`:''}${r.prescriber||r.responsible?`<p class="subtle">Responsável informado: ${e(r.prescriber||r.responsible)}. Sem verificação de credenciais.</p>`:''}${r.validUntil?`<p class="subtle">Validade informada: ${e(fmt(r.validUntil))}${Date.parse(r.validUntil)<Date.now()?' · Expirada':''}</p>`:''}<div class="actions section-gap">${kind==='boards'?`<button data-action="speak" data-text="${e(r.phrase)}">Falar frase</button>`:''}${kind==='prescriptions'?`<button data-action="medication-event" data-id="${r.id}">Registrar evento declarado</button>`:''}<button data-action="resource-edit" data-kind="${kind}" data-id="${r.id}">Editar</button><button class="danger" data-action="delete" data-kind="${kind}" data-id="${r.id}">Excluir</button></div>${kind==='prescriptions'?`<ul>${(state.medicationEvents||[]).filter(ev=>ev.prescriptionId===r.id).slice(-5).map(ev=>`<li>${e(fmt(ev.at))} · ${e({confirmed:'Tomada declarada',postponed:'Adiado',skipped:'Não tomado'}[ev.status])} <button class="ghost danger" data-action="delete" data-kind="medicationEvents" data-id="${ev.id}">Excluir evento</button></li>`).join('')}</ul>`:''}</li>`).join('')}</ul>`:empty('Nenhum registro. O preenchimento é opcional.')}</section>`;}
function resourceModal(kind,id){const config=globalThis.AuraResources?.[kind];if(!config)return;const record=(state[kind]||[]).find(r=>r.id===id)||{};openModal(config.singular,`<form id="resource-form" data-kind="${kind}" data-id="${id||''}">${config.fields.map(([field,label,type])=>`<label>${label}${type==='textarea'?`<textarea name="${field}" required maxlength="${kind==='documents'?50000:10000}">${e(record[field]||'')}</textarea>`:`<input name="${field}" type="${type}" value="${e(type==='date'?record[field]?.slice(0,10)||'':record[field]||'')}" maxlength="500" required>`}</label>`).join('')}<button class="primary">Salvar registro</button></form>`);}
function openModal(title, content) { returnFocus=document.activeElement; modal.innerHTML=`<header><h2 id="modal-title">${title}</h2><button class="icon-button ghost" data-action="close" aria-label="Fechar janela">×</button></header>${content}`; modal.showModal(); }
modal.addEventListener('close',()=>{ if(returnFocus?.isConnected) returnFocus.focus(); });
modal.addEventListener('cancel',event=>{if(modal.dataset.busy==='true')event.preventDefault();});
function taskModal(id) {
  const item = state.tasks.find(t=>t.id===id);
  let value = nowLocal();
  if(item){const d=new Date(item.startsAt);value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  openModal(item?'Editar atividade':'Uma atividade de cada vez',`<form id="task-form" data-id="${id||''}"><label>O que você quer fazer?<input name="title" value="${e(item?.title||'')}" maxlength="200" required autofocus></label><label>Data e hora neste computador<input name="startsAt" type="datetime-local" value="${value}" required></label><small>O horário digitado usa o fuso do computador: ${e(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Será exibido no fuso do seu perfil.</small><div class="form-row"><label>Tipo<select name="category">${[['pessoal','Pessoal'],['trabalho','Trabalho'],['estudo','Estudo'],['pausa','Pausa'],['consulta','Consulta'],['medicamento','Lembrete de prescrição existente']].map(([v,t])=>`<option value="${v}" ${item?.category===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Repetição<select name="recurrence">${[['none','Não repetir'],['daily','A cada 24 horas'],['weekly','A cada 7 dias']].map(([v,t])=>`<option value="${v}" ${item?.recurrence===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="subtle">Para medicamentos, registre apenas lembretes de uma prescrição existente. O sistema não valida dose ou tratamento.</p><button class="primary">Salvar atividade</button></form>`);
}
function entryModal(kind,id) {
  if ((kind==='journal'&&!hasConsent('health')) || (kind==='memories'&&!hasConsent('memory'))) { toast('Ative primeiro o consentimento em Privacidade.');location.hash='privacidade';return; }
  const item=state[kind].find(n=>n.id===id);
  openModal(({notes:'Sua nota',memories:'Memória sob seu controle',journal:'Relato pessoal',feedback:'Relato local de suporte'})[kind],`<form id="entry-form" data-kind="${kind}" data-id="${id||''}"><label>Título<input name="title" value="${e(item?.title||'')}" maxlength="200" required autofocus></label><label>Conteúdo<textarea name="content" maxlength="10000" required>${e(item?.content||'')}</textarea></label>${kind==='memories'?`<label>Finalidade<input name="purpose" value="${e(item?.purpose||'Personalização local')}" maxlength="200" required></label><label>Validade opcional<input name="expiresAt" type="date" value="${e(item?.expiresAt?.slice(0,10)||'')}"></label><small>Origem: declarada por você. O conteúdo não será usado para treinar modelos.</small>`:''}<button class="primary">Salvar registro</button></form>`);
}
function speak(text) { const target=document.querySelector('#speech-text');if(target)target.textContent=text;if(!('speechSynthesis'in window))return toast('Voz indisponível neste navegador. A mensagem continua visível.'); speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='pt-BR';utterance.onerror=()=>toast('A leitura não pôde ser concluída. A mensagem permanece em texto.');speechSynthesis.speak(utterance); }
function timerLabel(){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function act(action,button) {
  if(action==='assistant-example'){const input=document.querySelector('#chat');if(input){input.value=button.dataset.message||'';input.focus();}return;}
  if(action==='assistant-navigate'){if(routes.some(r=>r[0]===button.dataset.route))location.hash=button.dataset.route;return;}
  if(action==='install-web'){if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}return openModal('Usar como aplicativo',`<p>No menu do Chrome ou Edge, procure Instalar aplicativo. No Safari do iPhone/iPad, abra Compartilhar e Adicionar à Tela de Início. A opção depende do navegador.</p><p>O aplicativo usa este mesmo cofre do navegador. Preserve backups antes de limpar dados ou trocar de aparelho.</p><button data-action="close">Fechar</button>`);}
  if(action==='clear-retired-models'){if('caches'in globalThis)await caches.delete('aura-browser-ai-v1');return toast('Cache do modelo antigo removido. Seu cofre foi preservado.');}
  if(action==='storage-persist'){const granted=await navigator.storage?.persist?.();return toast(granted?'O navegador aceitou proteger o armazenamento contra remoção automática. Continue fazendo backups.':'O navegador não reservou armazenamento persistente. Seus dados continuam aqui; preserve backups.');}
  if(action==='import-vault')return openModal('Trazer seu cofre para o navegador',`<p>Escolha o backup criptografado exportado do AURA. O arquivo será aberto apenas neste aparelho; não será enviado a um servidor.</p><form id="import-vault-form"><label>Backup criptografado<input name="file" type="file" accept=".json,application/json" required></label><label>Senha do backup<input name="backupPassword" type="password" autocomplete="current-password" required></label><label>Digite IMPORTAR<input name="confirm" required autocomplete="off"></label><button class="primary">Importar cofre neste aparelho</button></form>`);
  const id=button.dataset.id,kind=button.dataset.kind;
  if(!demo&&!serverOffline&&['export','backup','erase','recovery-enable'].includes(action)){
    const auth=await api('session');if(!auth.reauthFresh){pendingSensitiveAction={action,dataset:{...button.dataset}};return openModal('Confirme sua senha para continuar',`<form id="reauth-form"><label>Senha atual do cofre<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Confirmar identidade</button></form>`);}
  }
  if(action==='close')return modal.close();
  if(action==='action-preview-new'){if(demo||serverOffline||offlineSession?.operations.length)throw new Error('A prévia de ação exige um cofre online sincronizado. Use a agenda manual na demonstração ou offline.');return openModal('Preparar uma atividade pessoal',`<form id="action-preview-form"><label>Atividade<input name="title" maxlength="200" required></label><label>Data e hora no computador<input name="startsAt" type="datetime-local" value="${nowLocal()}" required></label><button class="primary">Ver prévia antes de salvar</button></form>`);}
  if(action==='action-confirm'){state=await api(`actions/${id}/confirm`,'POST',{confirm:true});if(offlineSession){offlineSession.baseRevision=state.revision;await globalThis.AuraOffline.save(offlineSession,state);}modal.close();render();return toast('Atividade criada após sua confirmação.');}
  if(action==='recover')return openModal('Recuperar acesso ao cofre',`<p>Use o código criado anteriormente em Privacidade. Ele será consumido; depois crie um novo código. Sem senha, código ou backup acessível, não podemos recuperar o conteúdo.</p><form id="recover-form"><label>Código de recuperação<input name="code" autocomplete="off" required maxlength="100"></label><label>Nova senha do cofre<input name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="200" required></label><button class="primary">Usar código e definir nova senha</button></form>`);
  if(action==='recovery-enable'){if(demo||serverOffline)throw new Error('A criação do código exige um cofre online.');const result=await api('recovery/enable','POST',{confirm:'CRIAR RECUPERACAO'});return openModal('Guarde este código em local protegido',`<p>Qualquer pessoa com este código e acesso ao arquivo do cofre pode recuperar os dados. Guarde-o fora do computador. Ele não será exibido novamente por esta tela.</p><label>Código de recuperação<input readonly value="${e(result.code)}" autocomplete="off"></label><p class="subtle section-gap">Após usar o código, crie outro. A recuperação da conta AURA ID é separada da recuperação do cofre.</p><button data-action="close">Guardei o código em local protegido</button>`);}
  if(action==='restore'){if(demo||serverOffline)throw new Error('A restauração exige um cofre online.');return openModal('Restaurar uma cópia criptografada',`<p>Esta ação substitui o cofre atual. Baixe uma cópia antes de continuar. Confira a origem do arquivo; seu conteúdo será importado como dados, nunca como instruções.</p><form id="restore-form"><label>Arquivo de backup JSON<input name="file" type="file" accept=".json,application/json" required></label><label>Senha atual do cofre<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Senha que abre o backup<input name="backupPassword" type="password" autocomplete="off" required></label><label>Digite RESTAURAR<input name="confirm" autocomplete="off" required></label><button class="danger">Substituir o cofre pelo backup</button></form>`);}
  if(action==='reload'){location.reload();return;}
  if(action==='offline-enable'){if(demo)return toast('A demonstração não grava cópias offline.');if(serverOffline)throw new Error('Reconecte antes de atualizar a cópia.');return openModal('Ativar cópia essencial neste navegador',`<p>Esta cópia será protegida com a senha atual do cofre e substituirá uma cópia anterior deste navegador. Nenhum dado de saúde será incluído.</p><form id="offline-enable-form"><label>Confirme a senha do cofre<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Autorizar e criar cópia criptografada</button></form>`);}
  if(action==='offline-remove')return openModal('Remover a cópia deste navegador?',`<p>Alterações ainda não sincronizadas serão perdidas. Exporte uma cópia local antes, se precisar revisá-las.</p><button class="danger" data-action="offline-remove-confirm">Remover cópia e alterações locais</button>`);
  if(action==='offline-remove-confirm'){await globalThis.AuraOffline.remove();offlineSession=null;modal.close();if(serverOffline){state=null;serverOffline=false;welcome();}else render();return toast('Cópia offline removida deste navegador.');}
  if(action==='offline-export')return openModal('Exportar cópia local legível?',`<p>O arquivo contém agenda, notas e alterações pendentes em texto aberto. Guarde-o em local protegido.</p><button class="primary" data-action="offline-export-confirm">Confirmar exportação legível</button>`);
  if(action==='offline-export-confirm'){download(JSON.stringify({state:offlineSession?.state,operations:offlineSession?.operations},null,2),'aura-copia-offline-legivel.json');modal.close();return toast('Cópia legível exportada. Guarde-a em local protegido.');}
  if(action==='offline-sync'){
    const current=await api('status');if(current.identityRequired)return openModal('Entre novamente no AURA ID',`<p>Suas alterações estão criptografadas neste navegador. Entre no AURA ID e abra o cofre para sincronizar.</p><a class="button primary" href="/auth/login">Entrar no AURA ID</a>`);
    if(current.userSubject!==offlineSession.subject)throw new Error('A cópia offline pertence a outra conta. Entre na conta correspondente.');
    try{csrf=(await api('session')).csrf;}catch{return openModal('Abra o cofre online',`<p>Suas alterações estão guardadas. Recarregue e entre no cofre. A cópia offline será recuperada com a mesma senha.</p><button data-action="reload">Reabrir serviço online</button>`);}
    try{const next=await api('sync','POST',{subject:offlineSession.subject,baseRevision:offlineSession.baseRevision,operations:offlineSession.operations});state=next;offlineSession.operations=[];offlineSession.baseRevision=next.revision;serverOffline=false;await globalThis.AuraOffline.save(offlineSession,state);render();return toast('Alterações sincronizadas sem duplicação.');}
    catch(error){if(error.status!==409)throw error;return openModal('Há alterações nos dois lugares',`<p>Nada foi sobrescrito. Você pode exportar a cópia local para comparar, aplicar suas alterações sobre a versão atual ou usar os dados do servidor.</p><div class="stack"><button data-action="offline-export">Exportar cópia local para revisão</button><button data-action="offline-use-local" data-revision="${Number(error.details?.revision)||0}">Aplicar minhas alterações locais sobre a versão atual</button><button class="danger" data-action="offline-use-server">Descartar alterações locais e usar servidor</button></div>`);}
  }
  if(action==='offline-use-local'){offlineSession.baseRevision=Number(button.dataset.revision);modal.close();return act('offline-sync',{dataset:{}});}
  if(action==='offline-use-server'){state=await api('state');offlineSession.operations=[];offlineSession.baseRevision=state.revision;serverOffline=false;await globalThis.AuraOffline.save(offlineSession,state);modal.close();render();return toast('Mantida a versão do servidor.');}
  if(action==='resource-new')return resourceModal(kind);
  if(action==='resource-edit')return resourceModal(kind,id);
  if(action==='medication-event')return openModal('Evento declarado por você',`<p>O registro não confirma ingestão por sensor nem valida a prescrição.</p><form id="medication-form" data-id="${id}"><label>O que deseja registrar?<select name="status"><option value="confirmed">Declaro que tomei conforme a orientação existente</option><option value="postponed">Adiei</option><option value="skipped">Não tomei</option></select></label><label>Observação opcional<textarea name="note" maxlength="500"></textarea></label><button>Salvar declaração</button></form>`);
  if(action==='grant-new'){if(!identityInfo.enabled||demo)return toast('Use o iniciador Plataforma e entre com AURA ID para delegar acesso.');return openModal('Autorizar uma pessoa',`<form id="grant-form"><label>Nome da pessoa<input name="recipient" maxlength="120" required></label><label>Identificação AURA ID do destinatário<input name="targetSubject" maxlength="200" required></label><label>Finalidade<input name="purpose" maxlength="500" required></label><label>Válido até<input name="expiresAt" type="date" required></label><fieldset><legend>Informações permitidas</legend>${[['tasks','Agenda'],['notes','Notas'],['journal','Diário'],['prescriptions','Prescrições'],['carePlans','Cuidados'],['nutritionPlans','Alimentação'],['activityPlans','Atividades']].map(([v,t])=>`<label class="check"><input type="checkbox" name="scopes" value="${v}">${t}</label>`).join('')}</fieldset><p class="subtle">O acesso dependerá da sessão desbloqueada do titular. Nenhum convite será enviado automaticamente.</p><button class="primary">Autorizar os escopos escolhidos</button></form>`);}
  if(action==='grant-revoke'){await change('grants','PATCH',{revoked:true},id);return toast('Acesso revogado.');}
  if(action==='identity-logout'){window.AuraDesktop?.clearSchedule();const result=await(await fetch('/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'})).json();location.href=result.logoutUrl||'/';return;}
  if(action==='demo')return startDemo();
  if(action==='welcome-contrast'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='contrast'?'dark':'contrast';return;}
  if(action==='welcome-scale'){document.documentElement.classList.toggle('scale-150');return;}
  if(action==='lock'){if(globalThis.AURA_STATIC_DEMO){location.href='../';return;}const wasOffline=serverOffline;const locking=demo||wasOffline?Promise.resolve():api('lock','POST',{}).catch(()=>{});demo=false;state=null;csrf=null;conversation=[];offlineSession=null;serverOffline=false;clearInterval(timer);timer=null;window.speechSynthesis?.cancel();if(modal.open)modal.close();prefs();app.innerHTML='<main id="main" class="content"><h1>Cofre bloqueado.</h1><p role="status">Preparando a tela de acesso…</p></main>';await locking;if(wasOffline)return offlineWelcome();try{initialized=(await api('status')).initialized;}catch{}return welcome();}
  if(action==='task-new')return taskModal();
  if(action==='task-edit')return taskModal(id);
  if(action==='task-toggle'){
    const t=state.tasks.find(t=>t.id===id);
    await change('tasks','PATCH',{done:!t.done},id);return toast('Atividade atualizada.');
  }
  if(action==='task-snooze'){const t=state.tasks.find(t=>t.id===id);await change('tasks','PATCH',{startsAt:new Date(Math.max(Date.now(),Date.parse(t.startsAt))+600000).toISOString(),done:false},id);return toast('Atividade adiada por 10 minutos.');}
  if(action==='delete'){openModal('Excluir este registro?',`<p>O registro será removido do cofre local.</p><button class="danger" data-action="delete-confirm" data-kind="${kind}" data-id="${id}">Excluir registro</button>`);return;}
  if(action==='delete-confirm'){await change(kind,'DELETE',{},id);modal.close();return toast('Registro excluído.');}
  if(action==='entry-new')return entryModal(kind);
  if(action==='entry-edit')return entryModal(kind,id);
  if(action==='contact-new')return openModal('Uma pessoa de confiança',`<form id="contact-form"><label>Nome<input name="name" maxlength="120" required autofocus></label><label>Telefone<input name="phone" type="tel" maxlength="40" pattern="[+0-9 ()\-]+" required></label><small>O contato não receberá convite nem acesso aos seus dados.</small><button class="primary">Salvar contato</button></form>`);
  if(action==='urgent')return openModal('Seus contatos de ajuda',`<p>Escolha uma pessoa para abrir o discador do dispositivo. O AURA não envia chamados nem monitora emergências.</p>${contactList()}<p class="subtle section-gap">Em uma emergência, procure o serviço oficial de atendimento da sua região.</p><a class="button" href="#apoio" data-action="close">Gerenciar contatos</a>`);
  if(action==='speak')return speak(button.dataset.text);
  if(action==='stop-speech')return window.speechSynthesis?.cancel();
  if(action==='clear-chat'){conversation=[];render();return;}
  if(action==='consent'){await change('consents','POST',{scope:button.dataset.scope,granted:!hasConsent(button.dataset.scope)});return toast('Sua escolha foi registrada.');}
  if(action==='notifications'){if(!('Notification'in window))return toast('Notificações indisponíveis. Os alertas continuam na tela.');const permission=await Notification.requestPermission();return toast(permission==='granted'?'Notificações ativadas com a janela aberta.':'Permissão não concedida. Os alertas continuam na tela.');}
  if(action==='timer-toggle'){if(timer){clearInterval(timer);timer=null;render();return;}const end=Date.now()+seconds*1000;timer=setInterval(()=>{seconds=Math.max(0,Math.ceil((end-Date.now())/1000));const el=document.querySelector('#timer');if(el)el.textContent=timerLabel();if(!seconds){clearInterval(timer);timer=null;toast('Seu tempo de foco terminou. Faça uma pausa no seu ritmo.');render();}},500);render();return;}
  if(action==='timer-reset'||action==='timer-short'){clearInterval(timer);timer=null;seconds=action==='timer-short'?300:1500;render();return;}
  if(action==='export')return openModal('Exportar seus dados?',`<p>O arquivo JSON inclui todos os registros, inclusive diário e memórias, em texto legível. Guarde-o em local protegido.</p><button class="primary" data-action="export-confirm">Confirmar e baixar JSON</button>`);
  if(action==='export-confirm'){const data=demo?state:await api('export','POST',{confirm:'EXPORTAR'});download(JSON.stringify(data,null,2),'aura-exportacao.json');modal.close();return toast('Exportação criada.');}
  if(action==='backup'){if(demo)return toast('A demonstração não possui cofre para copiar.');const data=await api('backup','POST',{confirm:'BACKUP'});download(JSON.stringify(data),'aura-cofre-criptografado.json');return toast('Cópia criptografada criada. Guarde também a senha do cofre.');}
  if(action==='expired-delete'){for(const m of [...state.memories].filter(m=>m.expiresAt&&Date.parse(m.expiresAt)<=Date.now()))await change('memories','DELETE',{},m.id);return toast('Memórias expiradas excluídas.');}
  if(action==='erase')return openModal('Apagar todo o cofre?',`<p>Esta ação remove os registros deste aplicativo. Não remove exportações ou cópias externas.</p><form id="erase-form"><label>Digite APAGAR TUDO<input name="confirm" required autocomplete="off"></label><button class="danger">Apagar definitivamente o cofre local</button></form>`);
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const control=button instanceof HTMLButtonElement;if(control)button.disabled=true;try{await act(button.dataset.action,button);}catch(error){toast(error.message);}finally{if(control&&button.isConnected)button.disabled=false;}});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();
  const data=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;
  const inModal=modal.contains(form);if(inModal){modal.querySelector('[data-form-error]')?.remove();modal.dataset.busy='true';const close=modal.querySelector('[data-action=close]');if(close)close.disabled=true;}
  try {
    if(form.id==='auth-form'){if(!initialized&&data.password!==data.confirm)throw new Error('As senhas precisam ser iguais.');const result=await api(initialized?'unlock':'setup','POST',data);csrf=result.csrf;state=await api('state');initialized=true;if(globalThis.AuraOffline?.available()&&await globalThis.AuraOffline.exists()){try{const cached=await globalThis.AuraOffline.unlock(data.password);if(cached.subject===(identityInfo.user?.subject||'local')){offlineSession=cached;if(cached.operations.length){for(const k of ['tasks','notes','preferences'])state[k]=cached.state[k];}else{cached.baseRevision=state.revision;await globalThis.AuraOffline.save(cached,state);}}}catch{}}prefs();render(true);}
    if(form.id==='import-vault-form'){const file=form.querySelector('[name=file]').files[0];if(!file||file.size>20000000)throw new Error('Escolha um backup de até 20 MB.');let backup;try{backup=JSON.parse(await file.text());}catch{throw new Error('Arquivo JSON inválido.');}await api('import','POST',{...data,backup});initialized=true;modal.close();welcome();toast('Cofre importado. Abra-o com a senha do backup.');}
    if(form.id==='offline-enable-form'){await api('reauth','POST',{password:data.password});await change('consents','POST',{scope:'offline',granted:true});offlineSession=await globalThis.AuraOffline.create(data.password,identityInfo.user?.subject||'local',state);modal.close();render();toast('Cópia essencial criptografada criada neste navegador.');}
    if(form.id==='offline-unlock-form'){offlineSession=await globalThis.AuraOffline.unlock(data.password);state=offlineSession.state;serverOffline=true;identityInfo={};prefs();render(true);toast('Cópia offline aberta. Alterações serão guardadas para sincronização.');}
    if(form.id==='reauth-form'){await api('reauth','POST',{password:data.password});modal.close();const pending=pendingSensitiveAction;pendingSensitiveAction=null;if(pending)await act(pending.action,{dataset:pending.dataset});}
    if(form.id==='action-preview-form'){const result=await api('actions/preview','POST',{kind:'tasks',data:{title:data.title,startsAt:new Date(data.startsAt).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,category:'pessoal',recurrence:'none'}});modal.close();openModal('Confira antes de confirmar',`<p><strong>${e(result.preview.title)}</strong></p><p>${e(fmt(result.preview.startsAt))} · ${e(result.preview.timezone)}</p><p class="subtle">${e(result.source)}</p><button class="primary" data-action="action-confirm" data-id="${result.id}">Confirmar criação desta atividade</button>`);}
    if(form.id==='recover-form'){await api('recover','POST',data);await globalThis.AuraOffline?.remove();offlineSession=null;modal.close();state=null;welcome();toast('Senha redefinida. Entre novamente e crie um novo código de recuperação.');}
    if(form.id==='restore-form'){const file=form.querySelector('[name=file]').files[0];if(!file||file.size>20000000)throw new Error('Escolha um backup de até 20 MB.');if(data.confirm!=='RESTAURAR')throw new Error('Digite exatamente RESTAURAR.');let backup;try{backup=JSON.parse(await file.text());}catch{throw new Error('Arquivo JSON inválido.');}await api('restore','POST',{...data,backup});await globalThis.AuraOffline?.remove();window.AuraDesktop?.clearSchedule();offlineSession=null;state=null;csrf=null;modal.close();welcome();toast('Backup restaurado. Abra o cofre usando a senha do backup.');}
    if(form.id==='task-form'){const id=form.dataset.id;const startsAt=new Date(data.startsAt);if(!Number.isFinite(startsAt.getTime()))throw new Error('Confira a data e a hora.');await change('tasks',id?'PATCH':'POST',{...data,startsAt:startsAt.toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone},id);modal.close();toast('Atividade salva.');}
    if(form.id==='entry-form'){if(data.expiresAt)data.expiresAt=new Date(data.expiresAt+'T23:59:59').toISOString();await change(form.dataset.kind,form.dataset.id?'PATCH':'POST',data,form.dataset.id);modal.close();toast('Registro salvo.');}
    if(form.id==='contact-form'){await change('contacts','POST',data);modal.close();toast('Contato salvo.');}
    if(form.id==='resource-form'){if(data.validUntil)data.validUntil=new Date(data.validUntil+'T23:59:59').toISOString();await change(form.dataset.kind,form.dataset.id?'PATCH':'POST',data,form.dataset.id);modal.close();toast('Registro salvo sem validação clínica automática.');}
    if(form.id==='medication-form'){await change('medicationEvents','POST',{...data,prescriptionId:form.dataset.id,at:new Date().toISOString()});modal.close();toast('Declaração registrada.');}
    if(form.id==='document-import-form'){if(serverOffline)throw new Error('A importação de documentos exige o serviço local. A cópia offline é restrita à rotina essencial.');const file=form.querySelector('[name=file]').files[0],progress=document.querySelector('#import-progress');const imported=await globalThis.AuraImporters.text(file,message=>{if(progress)progress.textContent=message;});if(progress)progress.textContent='Texto extraído. Revise antes de salvar.';resourceModal('documents');const editor=modal.querySelector('#resource-form');for(const field of ['title','content','source'])editor.elements[field].value=imported[field];}
    if(form.id==='grant-form'){const scopes=new FormData(form).getAll('scopes');if(!scopes.length)throw new Error('Escolha pelo menos uma informação.');await change('grants','POST',{...data,scopes,expiresAt:new Date(data.expiresAt+'T23:59:59').toISOString()});modal.close();toast('Autorização registrada.');}
    if(form.id==='delegated-form'){if(demo)throw new Error('A demonstração não consulta outras contas.');const result=await api(`delegated/${encodeURIComponent(data.owner)}/${data.scope}`);document.querySelector('#delegated-result').innerHTML=`<p>Autorização vigente até ${e(fmt(result.expiresAt))}</p>${result.items.length?result.items.map(item=>`<article class="list-item"><h3>${e(item.title)}</h3><p class="prose">${e(item.content||item.instructions||'')}</p>${item.startsAt?`<small>${e(fmt(item.startsAt))}</small>`:''}</article>`).join(''):empty('Sem registros neste escopo.')}`;}
    if(form.id==='preferences-form'){await change('preferences','PATCH',{...data,scale:Number(data.scale),reducedMotion:!!data.reducedMotion,simple:!!data.simple});toast('Preferências salvas.');}
    if(form.id==='profile-form'){try{new Intl.DateTimeFormat('pt-BR',{timeZone:data.timezone});}catch{throw new Error('Use um fuso IANA válido, como America/Sao_Paulo.');}if(demo){Object.assign(state.profile,data);render();}else await change('preferences','PATCH',data);toast('Perfil atualizado.');}
    if(form.id==='search-form'){search=data.search;render();}
    if(form.id==='speak-form')speak(data.text);
    if(form.id==='chat-form'){
      const chatState=state;conversation.push({role:'user',text:data.message});let response;
      if(demo||serverOffline)response=(await import('./domain/native-engine.mjs')).nativeReply(data.message,state,{includeNotes:!!data.includeNotes,includeDocuments:!!data.includeDocuments});
      else response=await api('assistant','POST',{message:data.message,includeNotes:!!data.includeNotes,includeDocuments:!!data.includeDocuments});
      if(!state||state.profile!==chatState.profile)return;conversation.push({role:'assistant',...response});render();document.querySelector('#chat')?.focus();
    }
    if(form.id==='erase-form'){if(data.confirm!=='APAGAR TUDO')throw new Error('Digite exatamente APAGAR TUDO.');if(demo){state=blank('Visitante');modal.close();render();toast('Dados temporários da demonstração apagados.');return;}if(serverOffline)throw new Error('A exclusão do cofre exige conexão com o serviço. Remova a cópia offline separadamente.');await api('erase','POST',data);await globalThis.AuraOffline?.remove();window.AuraDesktop?.clearSchedule();state=null;csrf=null;demo=false;offlineSession=null;initialized=(await api('status')).initialized;modal.close();welcome();toast('Cofre local apagado.');}
  }catch(error){if(form.id==='auth-form')document.querySelector('#auth-error').textContent=error.message;else if(inModal&&modal.open){const alert=document.createElement('p');alert.dataset.formError='true';alert.className='error';alert.setAttribute('role','alert');alert.textContent=error.message;form.prepend(alert);}else toast(error.message);}finally{if(submit)submit.disabled=false;if(inModal){delete modal.dataset.busy;const close=modal.querySelector('[data-action=close]');if(close)close.disabled=false;}}
});
window.addEventListener('hashchange',()=>{if(modal.open)modal.close();if(state)render(true);});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('aura-vault-external-lock',async()=>{state=null;csrf=null;conversation=[];offlineSession=null;window.speechSynthesis?.cancel();if(modal.open)modal.close();try{initialized=(await api('status')).initialized;}catch{}prefs();welcome();toast('Cofre bloqueado em outra aba.');});
for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>lastInteraction=Date.now(),{passive:true});
setInterval(()=>{if(state&&!demo&&Date.now()-lastInteraction>15*60000)act('lock',{dataset:{}}).then(()=>toast('Cofre bloqueado após 15 minutos sem interação.'));},15000);
setInterval(()=>{if(!state)return;for(const t of state.tasks){if(!t.done&&Date.parse(t.startsAt)<=Date.now()&&!reminderShown.has(t.id+':'+t.startsAt)){reminderShown.add(t.id+':'+t.startsAt);toast(`Lembrete: ${t.title}. Abra Agenda para confirmar ou adiar.`);if('Notification'in window&&Notification.permission==='granted')new Notification('AURA OS · Lembrete',{body:'Você tem uma atividade pendente. Abra sua agenda.',tag:t.id});}}},15000);
async function init(){
  if(globalThis.AURA_STATIC_DEMO){startDemo();return;}
  if(globalThis.AURA_BROWSER_MODE){globalThis.AuraOffline=null;try{globalThis.AuraBrowserAPI=(await import('./browser-vault.mjs')).browserAPI;}catch{app.innerHTML='<main id="main" class="content"><h1>Não foi possível preparar o cofre do navegador.</h1><p>Recarregue com conexão à internet para atualizar os arquivos do aplicativo.</p></main>';return;}}
  if(globalThis.AURA_BROWSER_MODE){const index=routes.findIndex(r=>r[0]==='delegacao');if(index>=0)routes.splice(index,1);}
  try{
    if(!globalThis.AURA_BROWSER_MODE)try{identityInfo=await(await fetch('/auth/config')).json();}catch{}
    runtimeInfo=await api('status');initialized=runtimeInfo.initialized;
    try{csrf=(await api('session')).csrf;state=await api('state');prefs();render();}catch{welcome();}
  }catch{
    if(await globalThis.AuraOffline?.exists())offlineWelcome();
    else app.innerHTML='<main id="main" class="content"><h1>Abra o serviço local para continuar.</h1><p>Execute o iniciador AURA na pasta do projeto e recarregue esta página. A cópia offline precisa ser ativada antes da desconexão.</p><button data-action="reload">Recarregar</button></main>';
  }
  if('serviceWorker'in navigator)navigator.serviceWorker.register(globalThis.AURA_BROWSER_MODE?'./browser-sw.js':'/sw.js').catch(()=>{});
}
init();
